import type { ConfigContext, ExpoConfig } from 'expo/config';

// Lets Node load the TypeScript files that env.ts imports (src/lib/env-schema.ts).
import 'tsx/cjs';
// eslint-disable-next-line perfectionist/sort-imports -- must load after tsx/cjs
import { Env } from './env';

/**
 * Non-production builds use badged icons pre-generated by `pnpm icons:badge` (committed).
 * The app-icon-badge *config plugin* writes PNGs without awaiting them, which races the
 * Android icon step on EAS — so we generate once and pick per environment here.
 */
const iconSuffix = Env.isProduction ? '' : `-${Env.APP_ENV}`;

const SPLASH_BG_LIGHT = '#FFFFFF';
const SPLASH_BG_DARK = '#09090B';

const interFont = (file: string) => `node_modules/@expo-google-fonts/inter/${file}/Inter_${file}.ttf`;
const INTER_WEIGHTS = [
  { file: '400Regular', weight: 400 },
  { file: '500Medium', weight: 500 },
  { file: '600SemiBold', weight: 600 },
  { file: '700Bold', weight: 700 },
] as const;

export default ({ config }: ConfigContext): ExpoConfig => ({
  ...config,
  name: Env.client.APP_NAME,
  slug: Env.app.slug,
  owner: Env.expoOwner,
  version: Env.client.VERSION,
  scheme: Env.scheme,
  orientation: 'portrait',
  icon: `./assets/icon${iconSuffix}.png`,
  // 'automatic' lets the app follow the OS theme; the in-app theme switch overrides it.
  userInterfaceStyle: 'automatic',

  ios: {
    bundleIdentifier: Env.bundleId,
    supportsTablet: true,
    infoPlist: {
      ITSAppUsesNonExemptEncryption: false,
    },
  },

  android: {
    package: Env.bundleId,
    adaptiveIcon: {
      backgroundColor: '#E6F4FE',
      foregroundImage: `./assets/android-icon-foreground${iconSuffix}.png`,
      backgroundImage: './assets/android-icon-background.png',
      monochromeImage: './assets/android-icon-monochrome.png',
    },
    predictiveBackGestureEnabled: false,
    // Keep tokens/cached data out of Google cloud backups.
    allowBackup: false,
    blockedPermissions: [
      // Pulled in by dev tooling; Play flags it and the app never draws overlays.
      'android.permission.SYSTEM_ALERT_WINDOW',
    ],
  },

  web: {
    favicon: './assets/favicon.png',
  },

  // OTA: each build's EAS channel (eas.json) decides which updates it receives.
  // Launch never blocks on the network; downloaded updates apply on the next cold start.
  ...(Env.easProjectId && {
    updates: {
      url: `https://u.expo.dev/${Env.easProjectId}`,
      checkAutomatically: 'ON_LOAD',
      fallbackToCacheTimeout: 0,
    },
  }),
  // Hash of native deps + native config: an update only reaches binaries built from the
  // same native code, so JS that needs a newer native module can never crash an old build.
  runtimeVersion: { policy: 'fingerprint' },

  experiments: {
    typedRoutes: true,
    reactCompiler: true,
  },

  plugins: [
    'expo-router',
    [
      'expo-splash-screen',
      {
        image: './assets/splash-icon.png',
        imageWidth: 160,
        backgroundColor: SPLASH_BG_LIGHT,
        dark: { image: './assets/splash-icon.png', backgroundColor: SPLASH_BG_DARK },
      },
    ],
    [
      // Fonts are embedded natively at build time → no runtime font loading on startup.
      'expo-font',
      {
        ios: { fonts: INTER_WEIGHTS.map(w => interFont(w.file)) },
        android: {
          fonts: [
            {
              fontFamily: 'Inter',
              fontDefinitions: INTER_WEIGHTS.map(w => ({ path: interFont(w.file), weight: w.weight })),
            },
          ],
        },
      },
    ],
    'expo-image',
    // Tokens live in the keychain/keystore. No biometric prompt (add faceIDPermission if you
    // gate tokens behind Face ID); exclude secure-store data from Android backups.
    ['expo-secure-store', { faceIDPermission: false, configureAndroidBackup: true }],
    // Local: avoids "Java heap space" during Android resource merging.
    './plugins/with-gradle-memory',
  ],

  extra: {
    /** Validated runtime env, read by `@/lib/env`. */
    env: Env.client,
    ...(Env.easProjectId && { eas: { projectId: Env.easProjectId } }),
  },
});
